namespace Shader {

struct CompileSnapshot;
void ReadCompileSnapshotReg(const CompileSnapshot&, u32, u32, void*, size_t);
void RefreshCompileSnapshotFlat(const CompileSnapshot&, const PersistentSrtInfo&, std::vector<u32>&);
void ReadCompileSnapshotTess(const CompileSnapshot&, TessellationDataConstantBuffer&);

enum class Qualifier : u8 {
    None,
    Smooth,
    NoPerspective,
    PerVertex,
    Flat,
    Centroid,
    Sample,
};

/**
 * Contains general information generated by the shader recompiler for an input program.
 */
struct InfoPersistent {
    BufferResourceList buffers;
    ImageResourceList images;
    SamplerResourceList samplers;
    FMaskResourceList fmasks;

    struct UserDataMask {
        void Set(IR::ScalarReg reg) noexcept {
            mask |= 1 << static_cast<u32>(reg);
        }

        u32 Index(IR::ScalarReg reg) const noexcept {
            const u32 reg_mask = (1 << static_cast<u32>(reg)) - 1;
            return std::popcount(mask & reg_mask);
        }

        u32 NumRegs() const noexcept {
            return std::popcount(mask);
        }

        u32 mask;
    };
    UserDataMask ud_mask{};
    u32 fetch_shader_sgpr_base{};
    u32 shared_memory_scratch_size{};

    u64 pgm_hash{};

    s32 tess_consts_dword_offset = -1;
    IR::ScalarReg tess_consts_ptr_base = IR::ScalarReg::Max;
    HwStage hw_stage;
    SwStage sw_stage;

    u8 mrt_mask{};
    bool has_fetch_shader{};
    bool has_bitwise_xor{};
    bool uses_dma{};

    InfoPersistent() = default;
    InfoPersistent(HwStage hw_stage_, SwStage sw_stage_, u64 pgm_hash_)
        : hw_stage{hw_stage_}, sw_stage{sw_stage_}, pgm_hash{pgm_hash_} {}
};

struct Info : InfoPersistent {
    struct AttributeFlags {
        bool Get(IR::Attribute attrib, u32 comp = 0) const {
            return flags[Index(attrib)] & (1 << comp);
        }

        bool GetAny(IR::Attribute attrib) const {
            return flags[Index(attrib)];
        }

        void Set(IR::Attribute attrib, u32 comp = 0) {
            flags[Index(attrib)] |= (1 << comp);
        }

        u32 NumComponents(IR::Attribute attrib) const {
            return 4;
        }

        static size_t Index(IR::Attribute attrib) {
            return static_cast<size_t>(attrib);
        }

        std::array<u8, IR::NumAttributes> flags;
    };

    enum class ReadConstType {
        None = 0,
        Immediate = 1 << 0,
        Dynamic = 1 << 1,
    };

    struct Interpolation {
        Qualifier primary;
        Qualifier auxiliary;
    };

    /// Non-null only for an explicitly owned, transient compilation context.
    const CompileSnapshot* compile_snapshot{};
    // Only installed on the preparation worker's private Info, never a shared GPU Info.
    mutable SpeculativeReadState* speculative_reads{};
    std::span<const u32> user_data;
    std::vector<u32> flattened_ud_buf;
    PersistentSrtInfo srt_info;

    AttributeFlags loads{};
    AttributeFlags stores{};

    ReadConstType readconst_types{};
    CopyShaderData gs_copy_data;
    u32 uses_patches{};

    VAddr pgm_base;
    bool has_storage_images{};
    bool has_discard{};
    bool has_image_gather{};
    bool has_image_query{};
    bool has_readconst{};
    bool uses_buffer_atomic_float_min_max{};
    bool uses_image_atomic_float_min_max{};
    bool uses_lane_id{};
    bool uses_shader_clock{};
    /// bbport BB_LAYER_MEMORY: some guest buffer goes through the page table (IsPagedBuffer).
    bool uses_paged_buffers{};
    bool uses_group_quad{};
    bool uses_group_shuffle{};
    bool uses_group_ballot{};
    IR::Type shared_types{};
    bool uses_fp16{};
    bool uses_fp64{};
    bool uses_pack_10_11_11{};
    bool uses_unpack_10_11_11{};
    bool uses_buffer_int64_atomics{};
    bool uses_shared_int64_atomics{};
    bool stores_tess_level_outer{};
    bool stores_tess_level_inner{};
    bool translation_failed{};

    std::array<Interpolation, IR::NumParams> fs_interpolation{};

    Info() = default;
    Info(HwStage stage_, SwStage l_stage_, ShaderParams params)
        : InfoPersistent(stage_, l_stage_, params.hash), pgm_base{params.Base()},
          user_data{params.user_data} {}

    /// bbport: user data of this stage as a draw saw it. The GPU command thread refreshes
    /// user_data/flattened_ud_buf for every draw it decodes, while the draw recording thread
    /// (vk_draw_pipe.h) may still work on an earlier draw: that thread installs snapshots here.
    struct UdSnapshot {
        const Info* info;
        const u32* user_data;
        u32 user_data_size;
        const u32* flat;
        u32 flat_size;
        VAddr pgm_base;
    };
    static constexpr u32 MaxUdSnapshots = 6;
    static inline thread_local UdSnapshot ud_snapshots[MaxUdSnapshots];
    static inline thread_local u32 num_ud_snapshots = 0;

    const UdSnapshot* Snapshot() const noexcept {
        for (u32 i = 0; i < num_ud_snapshots; ++i) {
            if (ud_snapshots[i].info == this) {
                return &ud_snapshots[i];
            }
        }
        return nullptr;
    }
    std::span<const u32> UserData() const noexcept {
        if (const auto* snapshot = Snapshot()) [[unlikely]] {
            return {snapshot->user_data, snapshot->user_data_size};
        }
        return user_data;
    }
    std::span<const u32> FlatUserData() const noexcept {
        if (const auto* snapshot = Snapshot()) [[unlikely]] {
            return {snapshot->flat, snapshot->flat_size};
        }
        return flattened_ud_buf;
    }

    VAddr ProgramBase() const noexcept {
        if (const auto* snapshot = Snapshot()) [[unlikely]] {
            return snapshot->pgm_base;
        }
        return pgm_base;
    }

    template <typename T>
    inline T ReadUdSharp(u32 sharp_idx) const noexcept {
        return *reinterpret_cast<const T*>(&FlatUserData()[sharp_idx]);
    }

    template <typename T>
    T ReadUdReg(u32 ptr_index, u32 dword_offset) const {
        T data;
        if (compile_snapshot) {
            ReadCompileSnapshotReg(*compile_snapshot, ptr_index, dword_offset, &data, sizeof(data));
            return data;
        }
        const auto ud = UserData();
        if (speculative_reads) {
            const u64 offset = u64(dword_offset) * sizeof(u32);
            if (ptr_index == IR::NumScalarRegs) {
                if (offset > ud.size_bytes() || sizeof(T) > ud.size_bytes() - offset)
                    SpeculativeReadState::Reject();
                std::memcpy(&data, reinterpret_cast<const u8*>(ud.data()) + offset, sizeof(T));
            } else {
                if (ptr_index > ud.size() || 2 > ud.size() - ptr_index)
                    SpeculativeReadState::Reject();
                u64 pointer;
                std::memcpy(&pointer, ud.data() + ptr_index, sizeof(pointer));
                speculative_reads->Copy(&data, SpeculativeReadState::Address(
                    pointer & 0xFFFFFFFFFFFFULL, offset), sizeof(T));
            }
            return data;
        }
        const u32* base = ud.data();
        if (ptr_index != IR::NumScalarRegs) {
            std::memcpy(&base, &ud[ptr_index], sizeof(base));
            base = reinterpret_cast<const u32*>(VAddr(base) & 0xFFFFFFFFFFFFULL);
        }
        std::memcpy(&data, base + dword_offset, sizeof(T));
        return data;
    }

    void PushUd(Backend::Bindings& bnd, PushData& push) const {
        const auto ud = UserData();
        u32 mask = ud_mask.mask;
        while (mask) {
            const u32 index = std::countr_zero(mask);
            ASSERT(bnd.user_data < NUM_USER_DATA_REGS && index < NUM_USER_DATA_REGS);
            mask &= ~(1U << index);
            push.ud_regs[bnd.user_data++] = ud[index];
        }
    }

    void AddBindings(Backend::Bindings& bnd) const {
        bnd.buffer += buffers.size();
        bnd.unified += buffers.size() + images.size() + samplers.size();
        bnd.user_data += ud_mask.NumRegs();
    }

    void RefreshFlatBuf() {
        if (compile_snapshot) {
            RefreshCompileSnapshotFlat(*compile_snapshot, srt_info, flattened_ud_buf);
            return;
        }
        if (speculative_reads) {
            speculative_reads->PrepareFlat(srt_info, UserData(), flattened_ud_buf);
            ValidateSpeculativeFlat();
            return;
        }
        flattened_ud_buf.resize(srt_info.flattened_bufsize_dw);
        ASSERT(user_data.size() <= NUM_USER_DATA_REGS);
        std::memcpy(flattened_ud_buf.data(), user_data.data(), user_data.size_bytes());
        if (srt_info.walker_func &&
            !TryRunWatchedSrt(srt_info,user_data.data(),flattened_ud_buf.data(),pgm_hash,u32(sw_stage))) {
            
#if defined(__aarch64__)
            RunSrtWalker(srt_info,user_data.data(),flattened_ud_buf.data());
#else
            srt_info.walker_func(user_data.data(), flattened_ud_buf.data());
#endif
        }
    }

    void ValidateSpeculativeFlat() const {
        const auto validate = [this](const auto& fetch, size_t words) {
            // UNKNOWN_LOCATION intentionally means a null resource in the original path.
            for (size_t i = 0; i < words; ++i)
                if (fetch.offsets[i] == UNKNOWN_LOCATION) return;
            for (size_t i = 0; i < words; ++i)
                if (fetch.load_mask & (1u << i)) speculative_reads->RequireFlat(fetch.offsets[i]);
        };
        for (const auto& res : buffers) validate(res.sharp_fetch, 4);
        for (const auto& res : images) validate(res.sharp_fetch, res.is_r128 ? 4 : 8);
        for (const auto& res : samplers) {
            validate(res.sharp_fetch, 4);
            if (res.post_op == SharpFetchPostOp::DisableAnisoIfSingleLod)
                speculative_reads->RequireFlat(res.post_op_tsharp_dw3_off);
        }
        for (const auto& res : fmasks) speculative_reads->RequireFlat(res.sharp_idx, 8);
    }

    void ReadTessConstantBuffer(TessellationDataConstantBuffer& tess_constants) const {
        if (compile_snapshot) {
            ReadCompileSnapshotTess(*compile_snapshot, tess_constants);
            return;
        }
        ASSERT(tess_consts_dword_offset >= 0); // We've already tracked the V# UD
        auto buf = ReadUdReg<AmdGpu::Buffer>(static_cast<u32>(tess_consts_ptr_base),
                                             static_cast<u32>(tess_consts_dword_offset));
        VAddr tess_constants_addr = buf.base_address;
        if (speculative_reads) {
            speculative_reads->Copy(&tess_constants, tess_constants_addr, sizeof(tess_constants));
            return;
        }
        memcpy(&tess_constants,
               reinterpret_cast<TessellationDataConstantBuffer*>(tess_constants_addr),
               sizeof(tess_constants));
    }

    void Serialize(Serialization::Archive& ar) const;
    bool Deserialize(Serialization::Archive& ar);
};
// Recovery lives only inside Common::GuestCapture::TryCopy. This scope and every C++
// owner above it unwind normally; the previous reader is restored even on a failed spec.
struct ScopedSpeculativeReads {
    const Info& info;
    SpeculativeReadState* previous;
    ScopedSpeculativeReads(const Info& i, SpeculativeReadState& reads)
        : info{i}, previous{i.speculative_reads} { info.speculative_reads = &reads; }
    ~ScopedSpeculativeReads() { info.speculative_reads = previous; }
    ScopedSpeculativeReads(const ScopedSpeculativeReads&) = delete;
};
DECLARE_ENUM_FLAG_OPERATORS(Info::ReadConstType);

} // namespace Shader
